// Turn the comma or newline separated site list into one item per site.
const config = $('Config').first().json;

const sites = String(config.siteUrls || config.siteUrl || '')
  .split(/[,\n]/)
  .map((s) => s.trim().replace(/\/+$/, ''))
  .filter(Boolean);

const valid = [...new Set(sites)].filter((s) => /^https?:\/\//i.test(s));
if (valid.length === 0) {
  throw new Error('Config -> siteUrls must contain at least one URL starting with http:// or https://');
}

return valid.map((site) => ({ json: { site } }));

// Parse each site's sitemap and split entries into pages and child sitemaps.
// Falls back to checking just the homepage for sites without a sitemap.
const sites = $('Split Sites').all();
const responses = $input.all();

const decode = (s) => s
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'");

const out = [];

for (let i = 0; i < responses.length; i++) {
  const site = sites[i].json.site;
  const res = responses[i].json;

  // The HTTP node puts the response text in 'data' (some setups use 'body')
  const raw = typeof res.data === 'string' ? res.data : (typeof res.body === 'string' ? res.body : '');
  const body = (!res.error && (res.statusCode === undefined || res.statusCode === 200)) ? raw : '';

  let found = 0;
  for (const m of body.matchAll(/<loc>\s*([\s\S]*?)\s*<\/loc>/gi)) {
    const loc = decode(m[1].trim());
    const type = /\.xml(\?|$)/i.test(loc) ? 'sitemap' : 'page';
    out.push({ json: { url: loc, type, site } });
    found++;
  }

  if (found === 0) {
    out.push({ json: { url: site, type: 'page', site } });
  }
}

return out;

// Extract page URLs from each child sitemap (one level deep).
const children = $('Is Child Sitemap?').all(0); // items from the "true" branch
const responses = $input.all();
const decode = (s) => s.replace(/&amp;/g, '&');
const out = [];

for (let i = 0; i < responses.length; i++) {
  const site = children[i].json.site;
  const res = responses[i].json;
  if (res.error || (res.statusCode !== undefined && res.statusCode !== 200)) continue;
  const raw = typeof res.data === 'string' ? res.data : (typeof res.body === 'string' ? res.body : '');
  for (const m of raw.matchAll(/<loc>\s*([\s\S]*?)\s*<\/loc>/gi)) {
    const loc = decode(m[1].trim());
    if (!/\.xml(\?|$)/i.test(loc)) out.push({ json: { url: loc, type: 'page', site } });
  }
}

return out;

// Deduplicate page URLs and cap each site so runs stay fast.
const config = $('Config').first().json;
const maxPages = Number(config.maxPages) || 50;

const seen = new Set();
const perSite = {};
const out = [];

for (const item of $input.all()) {
  if (!item.json.url) continue;
  const url = item.json.url.split('#')[0];
  const site = item.json.site;
  if (seen.has(url)) continue;
  seen.add(url);
  perSite[site] = (perSite[site] || 0) + 1;
  if (perSite[site] > maxPages) continue;
  out.push({ json: { url, site } });
}

return out;

// Pull every <a href> out of each page, resolve to absolute URLs and deduplicate.
// URL handling is plain JS because the Code node sandbox has no URL class.
const config = $('Config').first().json;
const pages = $('Collect Pages').all();
const responses = $input.all();

const parseUrl = (url) => {
  const m = String(url).trim().match(/^(https?):\/\/([^\/?#]+)([^?#]*)(\?[^#]*)?/i);
  if (!m) return null;
  return { protocol: m[1].toLowerCase(), host: m[2].toLowerCase(), path: m[3] || '/', query: m[4] || '' };
};

const normalizePath = (path) => {
  const out = [];
  for (const seg of path.split('/')) {
    if (seg === '.') continue;
    if (seg === '..') { if (out.length > 1) out.pop(); continue; }
    out.push(seg);
  }
  return out.join('/') || '/';
};

const resolveHref = (href, page) => {
  let abs;
  if (/^https?:\/\//i.test(href)) abs = href;
  else if (/^[a-z][a-z0-9+.-]*:/i.test(href)) return null; // mailto:, tel:, javascript:, ...
  else if (href.startsWith('//')) abs = page.protocol + ':' + href;
  else if (href.startsWith('/')) abs = page.protocol + '://' + page.host + href;
  else if (href.startsWith('?')) abs = page.protocol + '://' + page.host + page.path + href;
  else {
    const dir = page.path.slice(0, page.path.lastIndexOf('/') + 1) || '/';
    abs = page.protocol + '://' + page.host + dir + href;
  }
  const parsed = parseUrl(abs);
  if (!parsed) return null;
  return parsed.protocol + '://' + parsed.host + normalizePath(parsed.path) + parsed.query;
};

const skipDomains = String(config.skipDomains || '')
  .split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);

const linkMap = new Map(); // url -> { pages, sites }

const addLink = (url, foundOn, site) => {
  if (!linkMap.has(url)) linkMap.set(url, { pages: new Set(), sites: new Set() });
  linkMap.get(url).pages.add(foundOn);
  linkMap.get(url).sites.add(site);
};

for (let i = 0; i < responses.length; i++) {
  const pageUrl = pages[i].json.url;
  const pageSite = pages[i].json.site;
  const res = responses[i].json;

  const html = typeof res.data === 'string' ? res.data : (typeof res.body === 'string' ? res.body : null);

  // The page itself did not load - queue it so the checker confirms and reports it
  if (res.error || html === null || (res.statusCode && res.statusCode >= 400)) {
    addLink(pageUrl, '(page listed in sitemap)', pageSite);
    continue;
  }

  const page = parseUrl(pageUrl);
  if (!page) continue;
  const siteHost = (parseUrl(pageSite) || page).host;

  for (const m of html.matchAll(/<a\s[^>]*href\s*=\s*["']([^"']+)["']/gi)) {
    const href = m[1].replace(/&amp;/g, '&').trim().split('#')[0];
    if (!href) continue;

    const link = resolveHref(href, page);
    if (!link) continue;

    const host = parseUrl(link).host;
    if (!config.checkExternalLinks && host !== siteHost) continue;
    if (skipDomains.some((d) => host === d || host.endsWith('.' + d))) continue;

    addLink(link, pageUrl, pageSite);
  }
}

return [...linkMap.entries()].map(([url, entry]) => ({
  json: { url, foundOn: [...entry.pages], sites: [...entry.sites] },
}));

// Decide per link: ok, broken, or needs a GET retry.
// Many servers reject HEAD (403/405/999) even though the page exists,
// so anything that is not a clean 2xx/3xx or a definite 404/410 gets rechecked.
const links = $('Extract Links').all();
const results = $input.all();
const out = [];

for (let i = 0; i < results.length; i++) {
  const link = links[i].json;
  const res = results[i].json;
  const status = res.error ? 0 : (res.statusCode || 0);

  let verdict;
  if (status >= 200 && status < 400) verdict = 'ok';
  else if (status === 404 || status === 410) verdict = 'broken';
  else verdict = 'retry';

  out.push({ json: { url: link.url, foundOn: link.foundOn, sites: link.sites, status, verdict } });
}

return out;

// Final verdict for links that were inconclusive over HEAD.
const retried = $('Needs GET Retry?').all(0); // items from the "true" branch
const results = $input.all();
const out = [];

for (let i = 0; i < results.length; i++) {
  const link = retried[i].json;
  const res = results[i].json;
  const status = res.error ? 0 : (res.statusCode || 0);
  const ok = status >= 200 && status < 400;

  out.push({ json: { url: link.url, foundOn: link.foundOn, sites: link.sites, status, verdict: ok ? 'ok' : 'broken' } });
}

return out;

// Summarise results into a single report item, grouped by site.
const all = $input.all().map((i) => i.json);
const broken = all.filter((l) => l.verdict === 'broken');
const sites = [...new Set(all.flatMap((l) => l.sites || []))].sort();

const lines = [];
for (const site of sites) {
  const siteLinks = all.filter((l) => (l.sites || []).includes(site));
  const siteBroken = siteLinks
    .filter((l) => l.verdict === 'broken')
    .sort((a, b) => a.url.localeCompare(b.url));
  lines.push(`${site} - checked ${siteLinks.length} links, ${siteBroken.length} broken`);
  for (const l of siteBroken) {
    const status = l.status === 0 ? 'unreachable (DNS error or timeout)' : `HTTP ${l.status}`;
    lines.push(`- ${l.url}`);
    lines.push(`  ${status} | found on: ${l.foundOn.join(', ')}`);
  }
  lines.push('');
}

const report = [
  `Link check for ${sites.length} site(s)`,
  `Checked ${all.length} unique links, found ${broken.length} broken.`,
  '',
  ...lines,
].join('\n').trim();

return [{
  json: {
    sites,
    siteCount: sites.length,
    checkedAt: new Date().toISOString(),
    totalLinks: all.length,
    brokenCount: broken.length,
    broken,
    report,
  },
}];
